/* 负责闭区间 [L,R]，编号 0 合法且能被任意正 k 整除。 */
#include <stdio.h>
int main(void)  {
    long long left, right, step;
    scanf("%lld%lld%lld", &left, &right, &step);
    long long answer = right / step;
    /* 先计算正倍数前缀；L>0 减到 L-1，L=0 则额外计入编号 0。 */
    if (left == 0)  {
        answer++;
    }
    else  {
        answer -= (left - 1) / step;
    }
    /* 输出数量而非倍数列表，64 位整数支持一万亿级端点。 */
    printf("%lld\n", answer);
    return 0;
}

